tool_outputs.commands:
cd /home/eval/pkgs
# validate big-order respects deps using awk
/home/eval/pkgs/bin/order /home/eval/pkgs/deps-big.txt > /tmp/big.txt; echo "exit:$?"
cat /tmp/big.txt
echo "--- validate ---"
awk '
  NR==FNR { pos[$1]=NR; next }
  {
    line=$0; sub(/#.*$/, "", line)
    c=index(line, ":"); if(c==0) next
    left=substr(line,1,c-1); right=substr(line,c+1)
    gsub(/^[ \t]+|[ \t]+$/, "", left)
    n=split(left,lp,/[ \t]+/); pkg=lp[1]; if(pkg=="") next
    m=split(right,dp,/[ \t]+/)
    for(i=1;i<=m;i++){ d=dp[i]; if(d=="") continue
      if(!(pkg in pos) || !(d in pos)){ printf "MISSING %s %s\n", pkg, d; bad=1 }
      else if(pos[d] >= pos[pkg]){ printf "VIOLATION %s(%d) depends on %s(%d)\n", pkg, pos[pkg], d, pos[d]; bad=1 }
    }
  }
  END{ if(!bad) print "OK: all deps before packages" }
' /tmp/big.txt /home/eval/pkgs/deps-big.txt

echo "--- determinism check: smallest ready? ---"
# brute force check determinism via independent awk implementation
awk '
  function trim(s){ gsub(/^[ \t\r]+|[ \t\r]+$/, "", s); return s }
  { line=$0; sub(/#.*$/, "", line); c=index(line,":"); if(c==0) next
    left=trim(substr(line,1,c-1)); right=substr(line,c+1)
    n=split(left,lp,/[ \t\r]+/); pkg=lp[1]; if(pkg=="") next
    nodes[pkg]=1
    m=split(right,dp,/[ \t\r]+/)
    for(i=1;i<=m;i++){ d=dp[i]; if(d=="") continue; nodes[d]=1; edge[pkg,d]=1 }
  }
  END{
    for(p in nodes) indeg[p]=0
    for(e in edge){ split(e, a, SUBSEP); indeg[a[1]]++ }
    n=0; for(p in nodes) sorted[++n]=p
    # bubble sort byte order (LC_ALL=C)
    for(i=1;i<=n;i++) for(j=i+1;j<=n;j++) if(sorted[j] < sorted[i]){ t=sorted[i];sorted[i]=sorted[j];sorted[j]=t }
    emitted_n=0
    while(1){
      found=""
      for(i=1;i<=n;i++){ p=sorted[i]; if(!done[p] && indeg[p]==0){ found=p; break } }
      if(found=="") break
      done[found]=1; print found
      for(e in edge){ split(e,a,SUBSEP); if(a[2]==found && !done[a[1]]) indeg[a[1]]-- }
    }
  }
' /home/eval/pkgs/deps-big.txt > /tmp/big2.txt
diff /tmp/big.txt /tmp/big2.txt && echo "deterministic OK"

echo "--- whitespace/comment edge tests ---"
printf '# comment\n  \nfoo :  bar\tbaz  # inline\nbar:\n  baz :\nfoo: bar # dup\n' > /tmp/edge.txt
cat /tmp/edge.txt
/home/eval/pkgs/bin/order /tmp/edge.txt; echo "exit:$?"
# expected: bar,baz then foo (bar and baz sorted: bar,baz)
echo "--- self-cycle ---"
printf 'x: x\ny:\n' > /tmp/self.txt
/home/eval/pkgs/bin/order /tmp/self.txt > /tmp/self_out.txt 2> /tmp/self_err.txt; echo "exit:$?"; echo "out:"; cat /tmp/self_out.txt; echo "err:"; cat /tmp/self_err.txt
echo "--- missing file ---"
# should exit non-zero, but not required; just checking no crash
